#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <arpa/inet.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define CACHE_DIR "/var/cache/dnscrypt"
#define MAX_DOMAIN 253
#define KEY_LEN 32
#define IV_LEN 16
#define BLOCK_SIZE 16

static unsigned char g_key[KEY_LEN];
static int g_initialized = 0;

typedef struct {
    char domain[MAX_DOMAIN + 1];
    uint32_t ip_addr;
    time_t timestamp;
    uint32_t ttl;
} dns_record_t;

static int init_encryption_key(void) {
    const char *keyfile = CACHE_DIR "/master.key";
    int fd = open(keyfile, O_RDONLY);
    if (fd < 0) {
        if (RAND_bytes(g_key, KEY_LEN) != 1) return -1;
        fd = open(keyfile, O_WRONLY | O_CREAT, 0600);
        if (fd < 0) return -1;
        write(fd, g_key, KEY_LEN);
        close(fd);
    } else {
        read(fd, g_key, KEY_LEN);
        close(fd);
    }
    g_initialized = 1;
    return 0;
}

static int encrypt_record(const dns_record_t *rec, unsigned char *out, int *out_len) {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[IV_LEN];
    int len, total = 0;

    if (RAND_bytes(iv, IV_LEN) != 1) return -1;
    memcpy(out, iv, IV_LEN);
    total += IV_LEN;

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, g_key, iv);
    EVP_EncryptUpdate(ctx, out + total, &len, (unsigned char *)rec, sizeof(*rec));
    total += len;
    EVP_EncryptFinal_ex(ctx, out + total, &len);
    total += len;
    EVP_CIPHER_CTX_free(ctx);
    *out_len = total;
    return 0;
}

static int domain_to_cachepath(const char *domain, char *path, size_t pathsz) {
    unsigned long hash = 5381;
    const char *p = domain;
    while (*p) { hash = ((hash << 5) + hash) + (unsigned char)*p; p++; }
    snprintf(path, pathsz, CACHE_DIR "/records/%08lx.enc", hash & 0xFFFFFFFF);
    return 0;
}

static int validate_cache_path(const char *path) {
    /* Ensure path is within cache directory */
    if (strncmp(path, CACHE_DIR "/records/", strlen(CACHE_DIR "/records/")) != 0)
        return -1;
    if (strstr(path, "..") != NULL)
        return -1;
    return 0;
}

static int persist_record(const char *domain, const dns_record_t *rec) {
    char path[512];
    unsigned char ciphertext[1024];
    int ct_len;
    struct stat st;
    int fd;

    if (!g_initialized && init_encryption_key() < 0) return -1;
    if (domain_to_cachepath(domain, path, sizeof(path)) < 0) return -1;
    if (validate_cache_path(path) < 0) return -1;
    if (encrypt_record(rec, ciphertext, &ct_len) < 0) return -1;

    /* Check if file exists - if so, verify it's a regular file before writing */
    if (lstat(path, &st) == 0) {
        if (!S_ISREG(st.st_mode)) {
            return -1; /* refuse to follow symlinks */
        }
    }

    /* TOCTOU window: between lstat check and open, attacker can replace file with symlink */
    fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    write(fd, ciphertext, ct_len);
    close(fd);
    return 0;
}

static int resolve_and_cache(const char *domain) {
    dns_record_t rec;
    struct in_addr addr;

    if (strlen(domain) > MAX_DOMAIN) return -1;
    /* Simplified resolution - in production would query upstream */
    if (inet_pton(AF_INET, "93.184.216.34", &addr) != 1) return -1;

    memset(&rec, 0, sizeof(rec));
    strncpy(rec.domain, domain, MAX_DOMAIN);
    rec.ip_addr = addr.s_addr;
    rec.timestamp = time(NULL);
    rec.ttl = 3600;

    return persist_record(domain, &rec);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <domain>\n", argv[0]);
        return 1;
    }

    mkdir(CACHE_DIR, 0755);
    mkdir(CACHE_DIR "/records", 0755);

    if (resolve_and_cache(argv[1]) < 0) {
        fprintf(stderr, "Resolution failed for %s\n", argv[1]);
        return 1;
    }
    printf("Cached resolution for %s\n", argv[1]);
    return 0;
}
